import{_ as r,o as a,c as i,a3 as s,j as e,a as n}from"./chunks/framework.z_KJ15Ep.js";const l="/bilder/unterricht-kataloge/kataloge-stundentafeln.jpg",d="/bilder/unterricht-kataloge/kataloge-stundentafeln-faecher-anlegen.jpg",k=JSON.parse('{"title":"Stundentafeln für Jahrgänge und Klassen vorbereiten","description":"","frontmatter":{"title":"Stundentafeln für Jahrgänge und Klassen vorbereiten","source_pageid":326,"source_revision":5443},"headers":[],"relativePath":"schild3/unterricht-kataloge/stundentafel-schulbezogene-kataloge.md","filePath":"schild3/unterricht-kataloge/stundentafel-schulbezogene-kataloge.md"}'),o={name:"schild3/unterricht-kataloge/stundentafel-schulbezogene-kataloge.md"};function u(g,t,c,h,p,f){return a(),i("div",null,[...t[0]||(t[0]=[s('<h1 id="stundentafeln-fur-jahrgange-und-klassen-vorbereiten" tabindex="-1">Stundentafeln für Jahrgänge und Klassen vorbereiten <a class="header-anchor" href="#stundentafeln-fur-jahrgange-und-klassen-vorbereiten" aria-label="Permalink to &quot;Stundentafeln für Jahrgänge und Klassen vorbereiten&quot;">​</a></h1><p>Fassen Sie Unterrichtsfächer zu Stundentafeln zusammen, die später einer Schülergruppe zugewiesen werden können. Legen Sie Geltungsbereich und die einzelnen Fächer fest.</p><p><a href="/bilder/unterricht-kataloge/kataloge-stundentafeln.jpg"><img src="'+l+'" alt="Über Kataloge ➜ Stundentafel können Fachzuordnungen als Vorlage definiert werden." loading="lazy"></a></p><p><em>Über Kataloge ➜ Stundentafel können Fachzuordnungen als Vorlage definiert werden.</em></p><p>Die Stundentafeln werden genutzt, um ganzen Klassen, Jahrgängen oder Schülergruppen auf einmal einen bestimmten Satz von Unterrichtsfächern zuzuordnen.</p><p>Typischerweise ist dies der Klassenunterricht. Diese Fächerzuordnung findet ohne Kursbezeichnung nur mit einer bestimmten Kursart statt: PUK - Pflichtunterricht für die (gesamte) Klasse.</p><p>Legen Sie im oberen Teil des Dialogs mit <strong>+</strong> eine neue Stundentafel an.</p><p>Geben Sie dieser einen <strong>Jahrgang</strong>, für den die Stundentafel gelten soll. Bleibt das Jahrgangsfeld leer, gilt ist die Stundentafel jahrgangsübergreifend.</p><p>In der Schulform <em>Berufskolleg</em> kann für die Stundentafel noch die Fachklasse gewählt werden, für die die Stundentafel gelten soll.</p><p><a href="/bilder/unterricht-kataloge/kataloge-stundentafeln-faecher-anlegen.jpg"><img src="'+d+'" alt="Legen Sie die Fächer an, die später den Schülern einer bestimmten Gruppe hinzugefügt werden sollen. Hier im Beispiel wird eine Stundentafeln für alle Klassen des Jahrgangs 5 definiert." loading="lazy"></a></p><p><em>Legen Sie die Fächer an, die später den Schülern einer bestimmten Gruppe hinzugefügt werden sollen. Hier im Beispiel wird eine Stundentafeln für alle Klassen des Jahrgangs 5 definiert.</em></p><p>Ist die Stundentafel angelegt, können im unteren Bereich des Fensters die einzelnen Fächer hinzugefügt werden.</p><p>Die Fächer können mit <strong>Kursart</strong> und <strong>Wochenstundenzahl</strong> angelegt werden.</p><p>Im Beispiel finden sich bei <strong>WZE</strong> so hohe Zahlen, da die Schule die WZE in <em>Minuten</em> erfasst. Üblicherweise werden hier 45-Miunuten-Blöcke eingetragen.</p><p>Variiert die Wochenstundenzahl innerhalb eines Jahrgangs, können Sie das Feld leer lassen oder einen Standardwert eintragen. Diesen Wert können Sie später anpassen.</p><p>Das Anlegen von Stundentafeln kann als Vorbereitung zur Zuweisung von Klassenunterricht gesehen werden.</p>',16),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,"Die Einrichtung der Stundentafeln legt noch keine Datensätze in den Leistungsdaten der Schüler an. Diese Zuordnung wird später über Gruppenprozesse vorgenommen.")],-1),e("div",{"data-hint-kind":"tip",class:"tip custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"tip","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 18h6m-5 3h4m-5-6c-4-3-4-9 0-11 5-3 11 1 9 6-.5 2-2 3-3 5v1H9z"})]),n("Tipp")]),e("p",null,"Erst mit dem Gruppenprozess Stundentafeln zuweisen werden diese bei den Schülern aktiviert. In aller Regel werden dann die fehlenden Angaben zum unterrichtenden Lehrer über den Gruppenprozess Klassenunterrichte bearbeiten vervollständigt.")],-1),e("hr",null,null,-1),e("p",null,[e("a",{href:"https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Stundentafel_(Schulbezogene_Kataloge)",target:"_blank",rel:"noreferrer"},"Originalartikel im Wiki"),n(" · Quellrevision 5443.")],-1)])])}const b=r(o,[["render",u]]);export{k as __pageData,b as default};
